function useInView(th=0.2){
  const r=useRef(null);const[v,setV]=useState(false);
  useEffect(()=>{const el=r.current;if(!el)return;
    const o=new IntersectionObserver(([e])=>{if(e.isIntersecting){setV(true);o.disconnect()}},{threshold:th});
    o.observe(el);return()=>o.disconnect()},[th]);
  return[r,v];
}
function useCount(end,dur=1800,go=false){
  const[v,setV]=useState(0);
  useEffect(()=>{if(!go)return;let s=0;const step=end/(dur/16);
    const id=setInterval(()=>{s+=step;if(s>=end){setV(end);clearInterval(id)}else setV(Math.floor(s))},16);
    return()=>clearInterval(id)},[go,end,dur]);
  return v;
}

